-- Raw SQL: FKs, integrity triggers, change log, app role. Hand-written; not generated by Prisma.

-- companyId FK on every business table
DO $$
DECLARE t text;
BEGIN
  FOR t IN SELECT table_name FROM information_schema.columns
           WHERE table_schema = 'public' AND column_name = 'companyId'
  LOOP
    EXECUTE format('ALTER TABLE %I ADD CONSTRAINT %I FOREIGN KEY ("companyId") REFERENCES "Company"(id) ON DELETE RESTRICT', t, t || '_companyId_fkey');
  END LOOP;
END $$;

ALTER TABLE "JournalLine" ADD CONSTRAINT "JournalLine_nonneg_chk" CHECK (debit >= 0 AND credit >= 0);

-- 1. Journal balance (deferred, evaluated at commit)
CREATE FUNCTION dd_check_journal_balanced() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE jid text; d numeric; c numeric;
BEGIN
  jid := CASE WHEN TG_OP = 'DELETE' THEN OLD."journalId" ELSE NEW."journalId" END;
  SELECT COALESCE(SUM(debit), 0), COALESCE(SUM(credit), 0) INTO d, c FROM "JournalLine" WHERE "journalId" = jid;
  IF d <> c THEN
    RAISE EXCEPTION 'Journal % is unbalanced: debit % <> credit %', jid, d, c USING ERRCODE = '23514';
  END IF;
  RETURN NULL;
END $$;

CREATE CONSTRAINT TRIGGER journal_line_balanced
  AFTER INSERT OR UPDATE OR DELETE ON "JournalLine"
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION dd_check_journal_balanced();

-- 2. Issued documents are immutable (except settlement/delivery/e-invoice status, amountPaid)
CREATE FUNCTION dd_guard_issued_doc() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE allowed text[] := ARRAY['settlementStatus','deliveryStatus','einvoiceStatus','amountPaid','updatedAt'];
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.status <> 'DRAFT' THEN
      RAISE EXCEPTION 'Issued % % cannot be deleted', TG_TABLE_NAME, OLD.id USING ERRCODE = '23514';
    END IF;
    RETURN OLD;
  END IF;
  IF OLD.status <> 'DRAFT' AND (to_jsonb(NEW) - allowed) IS DISTINCT FROM (to_jsonb(OLD) - allowed) THEN
    RAISE EXCEPTION 'Issued % % is immutable; use a credit note', TG_TABLE_NAME, OLD.id USING ERRCODE = '23514';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER invoice_immutable BEFORE UPDATE OR DELETE ON "Invoice" FOR EACH ROW EXECUTE FUNCTION dd_guard_issued_doc();
CREATE TRIGGER credit_note_immutable BEFORE UPDATE OR DELETE ON "CreditNote" FOR EACH ROW EXECUTE FUNCTION dd_guard_issued_doc();

-- lines of issued documents are immutable too (args: fk column, parent table)
CREATE FUNCTION dd_guard_issued_lines() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE pid text; st text;
BEGIN
  pid := (CASE WHEN TG_OP = 'DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END) ->> TG_ARGV[0];
  EXECUTE format('SELECT status::text FROM %I WHERE id = $1', TG_ARGV[1]) INTO st USING pid;
  IF st IS NOT NULL AND st <> 'DRAFT' THEN
    RAISE EXCEPTION 'Lines of issued % % are immutable', TG_ARGV[1], pid USING ERRCODE = '23514';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $$;

CREATE TRIGGER invoice_line_immutable BEFORE INSERT OR UPDATE OR DELETE ON "InvoiceLine"
  FOR EACH ROW EXECUTE FUNCTION dd_guard_issued_lines('invoiceId', 'Invoice');
CREATE TRIGGER credit_note_line_immutable BEFORE INSERT OR UPDATE OR DELETE ON "CreditNoteLine"
  FOR EACH ROW EXECUTE FUNCTION dd_guard_issued_lines('creditNoteId', 'CreditNote');

-- 3. No journal postings into LOCKED periods
CREATE FUNCTION dd_guard_locked_period() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE jid text; jd date; cid text;
BEGIN
  jid := CASE WHEN TG_OP = 'DELETE' THEN OLD."journalId" ELSE NEW."journalId" END;
  SELECT date, "companyId" INTO jd, cid FROM "Journal" WHERE id = jid;
  IF jd IS NOT NULL AND EXISTS (
    SELECT 1 FROM "Period" p WHERE p."companyId" = cid AND p.status = 'LOCKED' AND jd BETWEEN p.start AND p."end"
  ) THEN
    RAISE EXCEPTION 'Period containing % is locked', jd USING ERRCODE = '23514';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $$;

CREATE TRIGGER journal_line_period_guard BEFORE INSERT OR UPDATE OR DELETE ON "JournalLine"
  FOR EACH ROW EXECUTE FUNCTION dd_guard_locked_period();

-- 4. Change log for sync
CREATE FUNCTION dd_log_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE r jsonb;
BEGIN
  r := (CASE WHEN TG_OP = 'DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END) - 'passwordHash' - 'mfaSecret' - 'refreshTokenHash';
  INSERT INTO "ChangeLog"(id, "companyId", entity, "entityId", op, data, at, "updatedAt")
  VALUES (gen_random_uuid()::text, COALESCE(r ->> 'companyId', r ->> 'id'), TG_TABLE_NAME, r ->> 'id', TG_OP, r, now(), now());
  RETURN NULL;
END $$;

DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['Company','Branch','User','Role','UserRole','Account','Period','TaxCode','Customer','Item','NumberSequence',
    'Quote','QuoteLine','Invoice','InvoiceLine','CreditNote','CreditNoteLine','Payment','Allocation','Journal','JournalLine',
    'IssueSnapshot','Document','AuditEvent']
  LOOP
    EXECUTE format('CREATE TRIGGER %I AFTER INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION dd_log_change()', 'changelog_' || t, t);
  END LOOP;
END $$;

-- 5. App role: append-only audit log
DO $$ BEGIN
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'ddinvoice_app') THEN
    CREATE ROLE ddinvoice_app NOLOGIN; -- login + password are granted out-of-band at provisioning
  END IF;
END $$;
GRANT USAGE ON SCHEMA public TO ddinvoice_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA public TO ddinvoice_app;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO ddinvoice_app;
REVOKE UPDATE, DELETE, TRUNCATE ON "AuditEvent" FROM ddinvoice_app;
